# AnuDownloader - incremental modpack installer/updater
# Shows available modpacks as banner tiles, lets the user pick which launcher
# (Modrinth / CurseForge / TLauncher) to install into by clicking its logo,
# auto-detecting that launcher's folder across any drive, and only downloads
# files that are new or changed vs what's already on disk.

$ProgressPreference = 'SilentlyContinue'
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

$AppVersion = "2.16.2"
$ConfigDir  = Join-Path $env:APPDATA "AnuDownloader"
$ConfigFile = Join-Path $ConfigDir "config.json"
# jsDelivr kept serving a stale index.json for 10-30 minutes after a purge it
# reported as finished, three releases in a row. raw.githubusercontent.com
# honours a unique query string as a fresh URL, so every fetch bypasses its
# cache entirely and a published version is visible within seconds.
$IndexUrl   = "https://raw.githubusercontent.com/anubissxd/minecraft-servers/main/distribution/index.json"
function Get-AnuIndexUrl { return "$IndexUrl?nocache=$([DateTime]::UtcNow.Ticks)" }
$CacheDir   = Join-Path $ConfigDir "cache"

foreach ($d in @($ConfigDir, $CacheDir)) {
    if (-not (Test-Path $d)) { New-Item -ItemType Directory -Path $d -Force | Out-Null }
}

# Turkish (and some other) Windows locales make Java's own default
# String.toUpperCase()/toLowerCase() mangle plain ASCII (the classic "Turkish
# I" bug: i/I don't round-trip), which corrupts mod registry name lookups
# and can even corrupt files a launcher writes about itself - crashes that
# no mods/config file we ship can fix, only forcing the JVM's own locale can.
# JAVA_TOOL_OPTIONS is picked up by every JVM that starts afterwards
# (TLauncher's own process included, not just the game it launches), so this
# needs to be a persistent user env var, not just a per-run process one.
# Merge rather than overwrite in case the player already has JAVA_TOOL_OPTIONS
# set for something else (extra heap flags etc).
try {
    $existingJavaOpts = [Environment]::GetEnvironmentVariable("JAVA_TOOL_OPTIONS", "User")
    if (-not $existingJavaOpts) { $existingJavaOpts = "" }
    if ($existingJavaOpts -notmatch "user\.language") {
        $mergedJavaOpts = ($existingJavaOpts + " -Duser.language=en -Duser.country=US").Trim()
        [Environment]::SetEnvironmentVariable("JAVA_TOOL_OPTIONS", $mergedJavaOpts, "User")
    }
} catch { }

function Load-Config {
    if (Test-Path $ConfigFile) {
        try { return Get-Content $ConfigFile -Raw | ConvertFrom-Json } catch { return $null }
    }
    return $null
}
function Save-Config($cfg) {
    $cfg | ConvertTo-Json -Depth 6 | Set-Content -Path $ConfigFile -Encoding UTF8
}
function Get-FileSha256($path) {
    (Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLower()
}

# Invoke-WebRequest/Invoke-RestMethod throw inside this -noConsole compiled
# exe (they try to write to a progress stream that doesn't exist without a
# console host, even with $ProgressPreference silenced), so every network
# call in the app goes through raw HttpWebRequest instead.
function Get-AnuUrlHeaders([string]$url, [string]$method = "GET", [hashtable]$extraHeaders = @{}) {
    $req = [System.Net.HttpWebRequest]::Create($url)
    $req.Method = $method
    foreach ($k in $extraHeaders.Keys) { $req.Headers.Add($k, $extraHeaders[$k]) }
    $resp = $req.GetResponse()
    try { return $resp.Headers } finally { $resp.Close() }
}

function Save-AnuUrlToFile([string]$url, [string]$destPath) {
    if (Test-Path -LiteralPath $destPath) {
        # Modrinth App (and others) hardlink identical mod files from a
        # shared cache to save disk space, and those hardlinked files are
        # read-only by design. File.Create can't overwrite a read-only file
        # (Access Denied), and even if it could, writing in place would
        # corrupt that same physical data for every other hardlink pointing
        # at it. Deleting the directory entry first only unlinks THIS copy -
        # the shared cache blocks are untouched - then a fresh file is
        # created with its own new data.
        try { [System.IO.File]::SetAttributes($destPath, [System.IO.FileAttributes]::Normal) } catch { }
        Remove-Item -LiteralPath $destPath -Force -ErrorAction SilentlyContinue
    }
    $req = [System.Net.HttpWebRequest]::Create($url)
    $resp = $req.GetResponse()
    $stream = $resp.GetResponseStream()
    $fs = [System.IO.File]::Create($destPath)
    try {
        $buffer = New-Object byte[] 65536
        while (($read = $stream.Read($buffer, 0, $buffer.Length)) -gt 0) {
            $fs.Write($buffer, 0, $read)
        }
    } finally {
        $fs.Close(); $stream.Close(); $resp.Close()
    }
}

function Get-AnuUrlText([string]$url, [hashtable]$extraHeaders = @{}) {
    $req = [System.Net.HttpWebRequest]::Create($url)
    foreach ($k in $extraHeaders.Keys) { $req.Headers.Add($k, $extraHeaders[$k]) }
    $resp = $req.GetResponse()
    $stream = $resp.GetResponseStream()
    $reader = New-Object System.IO.StreamReader($stream)
    try { return $reader.ReadToEnd() } finally { $reader.Close(); $stream.Close(); $resp.Close() }
}
function Image-FromBase64([string]$b64) {
    $bytes = [System.Convert]::FromBase64String($b64)
    $stream = New-Object System.IO.MemoryStream(,$bytes)
    return [System.Drawing.Image]::FromStream($stream)
}

$cfg = Load-Config
if (-not $cfg) { $cfg = [PSCustomObject]@{ targets = @{} } }
if (-not ($cfg.PSObject.Properties.Name -contains 'targets')) {
    $cfg | Add-Member -NotePropertyName targets -NotePropertyValue @{} -Force
}

