function Get-PackVersionText($pack) {
    $verBits = @($pack.mc_version, $pack.loader) | Where-Object { $_ }
    $verText = $verBits -join " 一 "
    if ($pack.loader_version) { $verText += " $($pack.loader_version)" }
    return $verText
}

function Try-ResolveTarget {
    if (-not $script:selectedPack -or -not $script:selectedLauncherData) { return }
    $data = $script:selectedLauncherData
    $pack = $script:selectedPack
    $found = & $data.Finder $pack.folder_name
    if ($found) {
        Set-ChosenTarget $found
    } elseif ($data.Label -eq "CurseForge") {
        Show-AnuDialog "CurseForge için önce `"$($pack.name)`" adlı bir profil oluştur.`n`nSürüm: $(Get-PackVersionText $pack)" | Out-Null
    } elseif ($data.Label -eq "TLauncher") {
        Show-AnuDialog "TLauncher'da önce `"$($pack.name)`" adlı bir profil oluştur.`n`nSürüm: $(Get-PackVersionText $pack)`n`nProfil versions klasöründe oluşur - şimdi o profilin klasörünü seç." | Out-Null
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = "$($pack.name) için TLauncher profilinin klasörünü seç"
        $versionsDir = Join-Path $env:APPDATA ".minecraft\versions"
        if (Test-Path $versionsDir) { $dlg.SelectedPath = $versionsDir }
        if ($dlg.ShowDialog() -eq "OK") { Set-ChosenTarget $dlg.SelectedPath }
    } else {
        Show-AnuDialog "$($data.Label) için otomatik klasör bulunamadı.`nLütfen klasörü kendin seç." | Out-Null
        $dlg = New-Object System.Windows.Forms.FolderBrowserDialog
        $dlg.Description = "$($pack.name) için $($data.Label) profil klasörünü seç"
        if ($dlg.ShowDialog() -eq "OK") { Set-ChosenTarget $dlg.SelectedPath }
    }
}

function Make-LauncherTile($logoImg, $label, $finder) {
    $tile = New-Object System.Windows.Forms.Panel
    $tile.Size = New-Object System.Drawing.Size((Sz 54),(Sz 54))
    $tile.Margin = New-Object System.Windows.Forms.Padding((Sz 3))
    $tile.Cursor = [System.Windows.Forms.Cursors]::Hand
    Set-RoundedFill $tile 10 $ColPanel $ColBgElev
    $tile | Add-Member -NotePropertyName Selected -NotePropertyValue $false -Force

    $pic = New-Object System.Windows.Forms.PictureBox
    $pic.Image = $null
    $pic.SizeMode = "Zoom"
    $pic.Location = New-Object System.Drawing.Point(0,0)
    $pic.Size = New-Object System.Drawing.Size((Sz 54),(Sz 54))
    $pic | Add-Member -NotePropertyName SourceImage -NotePropertyValue $logoImg -Force
    $tile.Controls.Add($pic)

    # Region-clipping a PictureBox gives hard, pixelated corners (Region has no
    # anti-aliasing). Instead render the logo at 4x into an offscreen bitmap,
    # clip it there, then draw that back down at target size - the downscale
    # blends the hard clip edge into a smooth one.
    $pic.Add_Paint({
        param($s, $e)
        $scale = 4
        $sw = [Math]::Max(1, $s.Width * $scale)
        $sh = [Math]::Max(1, $s.Height * $scale)
        $temp = New-Object System.Drawing.Bitmap $sw, $sh, ([System.Drawing.Imaging.PixelFormat]::Format32bppArgb)
        $tg = [System.Drawing.Graphics]::FromImage($temp)
        $tg.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $tg.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic
        $path = Get-RoundedPath $sw $sh (10 * $scale)
        $tg.SetClip($path)
        $tg.DrawImage($s.SourceImage, 0, 0, $sw, $sh)
        $tg.Dispose(); $path.Dispose()

        $e.Graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
        $e.Graphics.InterpolationMode = [System.Drawing.Drawing2D.InterpolationMode]::HighQualityBilinear
        $e.Graphics.PixelOffsetMode = [System.Drawing.Drawing2D.PixelOffsetMode]::HighQuality
        $e.Graphics.DrawImage($temp, 0, 0, $s.Width, $s.Height)
        $temp.Dispose()
    }.GetNewClosure())

    $pic.Add_Paint({
        param($s, $e)
        if ($s.Parent.Selected) {
            $e.Graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
            $path = Get-RoundedPath ($s.Width - 2) ($s.Height - 2) 9
            $e.Graphics.TranslateTransform(1, 1)
            $pen = New-Object System.Drawing.Pen($ColSelect, 2.6)
            $e.Graphics.DrawPath($pen, $path)
            $e.Graphics.ResetTransform()
            $pen.Dispose(); $path.Dispose()
        }
    }.GetNewClosure())

    $tile.Tag = @{ Label = $label; Finder = $finder }
    $tile.Add_Click({ Handle-LauncherClick $this })
    $pic.Add_Click({ Handle-LauncherClick $this })

    $script:launcherTiles += $tile
    return $tile
}

function Handle-LauncherClick($sender) {
    $tile = if ($sender -is [System.Windows.Forms.Panel]) { $sender } else { $sender.Parent }
    $data = $tile.Tag
    if ($tile.Selected) {
        $tile.Selected = $false
        $tile.Invalidate($true)
        $script:selectedLauncherData = $null
        $script:selectedTarget = $null
        $txtChosen.Text = ""
        Set-ButtonEnabledState $btnUpdate $false
        return
    }
    foreach ($t in $script:launcherTiles) { $t.Selected = $false; $t.Invalidate($true) }
    $tile.Selected = $true
    $tile.Invalidate($true)
    $script:selectedLauncherData = $data
    Try-ResolveTarget
}

