# Native scrollbar (classic square/white, arrows) clashes with the rest of the
# UI's flat rounded look. Mouse-wheel scrolling still works without it, so we
# just keep it permanently hidden instead of styling it - WinForms re-shows it
# on every layout pass, hence re-hiding on each Layout event.
[void]$panelPacks.Handle
$SB_VERT = 1
[Anu.Native]::ShowScrollBar($panelPacks.Handle, $SB_VERT, $false) | Out-Null
$panelPacks.Add_Layout({ [Anu.Native]::ShowScrollBar($panelPacks.Handle, 1, $false) | Out-Null }.GetNewClosure())

function Show-AnuPatchNotes([string]$title, [string]$text) {
    $w = [int]($form.ClientSize.Width * 0.9)
    $h = [int]($form.ClientSize.Height * 0.9)

    $dlg = New-Object System.Windows.Forms.Form
    $dlg.Text = "$title - Yama Notları"
    $dlg.ClientSize = New-Object System.Drawing.Size($w, $h)
    $dlg.FormBorderStyle = "FixedDialog"
    $dlg.StartPosition = "CenterScreen"
    $dlg.MaximizeBox = $false
    $dlg.MinimizeBox = $false
    $dlg.BackColor = $ColBg
    $dlg.Icon = $AppIcon

    # sag tarafta scrollbar/rahat kaydirma icin bosluk birak
    $rightPad = 24
    $box = New-Object System.Windows.Forms.RichTextBox
    $box.ReadOnly = $true
    $box.BorderStyle = "None"
    $box.BackColor = $ColBg
    $box.ForeColor = [System.Drawing.Color]::White
    $box.Font = New-Object System.Drawing.Font("Segoe UI", 10)
    $box.Location = New-Object System.Drawing.Point(15, 15)
    $box.Size = New-Object System.Drawing.Size(($w - 30 - $rightPad), ($h - 65))
    $box.DetectUrls = $false
    $box.ScrollBars = "None"

    # cok basit markdown: "## " basliga, "- "/"* " madde isaretine cevrilir
    $normalFont = $box.Font
    $headingFont = New-Object System.Drawing.Font("Segoe UI", 13, [System.Drawing.FontStyle]::Bold)
    $lines = ($text -replace "`r`n", "`n") -split "`n"
    foreach ($line in $lines) {
        $start = $box.TextLength
        if ($line -match '^\s*##\s+(.*)$') {
            $box.AppendText("$($matches[1])`n")
            $box.Select($start, $box.TextLength - $start)
            $box.SelectionFont = $headingFont
        } elseif ($line -match '^\s*[-*]\s+(.*)$') {
            $box.AppendText("•  $($matches[1])`n")
            $box.Select($start, $box.TextLength - $start)
            $box.SelectionFont = $normalFont
        } else {
            $box.AppendText("$line`n")
            $box.Select($start, $box.TextLength - $start)
            $box.SelectionFont = $normalFont
        }
    }
    $box.Select(0, 0)

    # tasma varsa scrollbar goster, yoksa gizli kalsin
    if ($box.TextLength -gt 0) {
        $lastPos = $box.GetPositionFromCharIndex($box.TextLength - 1)
        if (($lastPos.Y + $box.Font.Height) -gt $box.ClientSize.Height) {
            $box.ScrollBars = "Vertical"
        }
    }

    $box.TabStop = $false
    $box.Add_Enter({ [Anu.Native]::HideCaret($box.Handle) | Out-Null }.GetNewClosure())
    $box.Add_MouseDown({ [Anu.Native]::HideCaret($box.Handle) | Out-Null }.GetNewClosure())
    $dlg.Controls.Add($box)

    $btnClose = New-Object System.Windows.Forms.Button
    $btnClose.Text = "Kapat"
    $btnClose.Location = New-Object System.Drawing.Point(($w - 110), ($h - 42))
    $btnClose.Size = New-Object System.Drawing.Size(95, 30)
    $btnClose.BackColor = $ColPanel2
    $btnClose.ForeColor = [System.Drawing.Color]::White
    $btnClose.FlatStyle = "Flat"
    $btnClose.Add_Click({ $dlg.Close() }.GetNewClosure())
    $dlg.Controls.Add($btnClose)
    $dlg.AcceptButton = $btnClose

    $box.Add_GotFocus({ $btnClose.Focus() }.GetNewClosure())
    $dlg.ActiveControl = $btnClose

    [void]$dlg.ShowDialog()
}

Add-ButtonClick $btnPatchNotes "Önce bir mod paketi seç." {
    $url = $script:selectedPack.patchnotes_url
    if ([string]::IsNullOrWhiteSpace($url)) {
        Show-AnuDialog "Bu paket için yama notu henüz eklenmemiş." | Out-Null
        return
    }
    $win = New-AnuProgressWindow "Yama notları getiriliyor..."
    $win.Bar.Style = "Marquee"
