    }
}

function Test-AnuSeedOnlyPath($manifestPath) {
    # These ship with the pack so a fresh install is complete, but the game
    # rewrites them itself afterwards (mod configs on launch, Palladium's
    # documentation dump, Connector's remapped-jar cache). Re-syncing them
    # would overwrite the player's own settings and, because the file changes
    # again on the next launch, every update check would download it forever.
    if (-not $manifestPath) { return $false }
    $p = $manifestPath -replace '\\', '/'
    return ($p -like "config/*" -or $p -like "mods/documentation/*" -or $p -like "mods/.connector/*")
}

function Get-ManifestRelPath($f) {
    # New manifests carry a "path" (e.g. "config/foo.toml"); legacy manifests
    # only had a bare filename, which always meant mods\<filename>.
    if ($f.path) { return ($f.path -replace '/', [IO.Path]::DirectorySeparatorChar) }
    return (Join-Path "mods" $f.filename)
}

function Close-AnuLauncherApps {
    # Close the launcher UIs (not the game itself, which runs as its own
    # separate process once started) before installing/updating, so when the
    # player reopens them they pick up the freshly-set JAVA_TOOL_OPTIONS env
    # var (already-running processes never see an env var set after they
    # started - only new ones do).
    foreach ($name in @("Modrinth App", "CurseForge")) {
        Get-Process -Name $name -ErrorAction SilentlyContinue | Stop-Process -Force -ErrorAction SilentlyContinue
    }
    # TLauncher's own process name varies by build/version, so match its
    # window title instead of guessing an exe name.
    Get-Process -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowTitle -like "*TLauncher*" } | Stop-Process -Force -ErrorAction SilentlyContinue
}

function Close-AnuGameProcess([string]$profileRoot) {
    # If the game itself (or a crashed-but-still-running instance) is open
    # for this exact profile, its JVM holds an open file handle on every mod
    # jar it loaded, and overwriting a locked file fails with Access Denied -
    # this was silently causing partial "N files failed" results. Only kill
    # java processes whose command line references THIS profile's own path,
    # never a blind javaw.exe sweep (that could be a totally unrelated game).
    try {
        $procs = Get-CimInstance Win32_Process -Filter "Name='javaw.exe' OR Name='java.exe'" -ErrorAction SilentlyContinue
        foreach ($proc in $procs) {
            if ($proc.CommandLine -and $proc.CommandLine.Contains($profileRoot)) {
                Stop-Process -Id $proc.ProcessId -Force -ErrorAction SilentlyContinue
                Start-Sleep -Milliseconds 500
            }
        }
    } catch { }
}

function Set-AnuLauncherJvmArgs([string]$profileRoot, [string]$launcherLabel) {
    # A JAVA_TOOL_OPTIONS env var does NOT reach the game's JVM on this
    # machine's launchers - they build a clean argument list themselves
    # rather than inheriting the parent environment, so the Turkish-locale
    # fix has to be written into each launcher's own per-profile JVM args
    # instead. Best-effort: never blocks the update if a launcher's config
    # format doesn't match what's expected here.
    $localeArgs = "-Duser.language=en -Duser.country=US"
    try {
        if ($launcherLabel -eq "TLauncher") {
            # The version json shares the profile folder's own name
            # (e.g. versions\asd\asd.json), alongside TLauncherAdditional.json.
            $folderName = Split-Path $profileRoot -Leaf
            $versionJsonPath = Join-Path $profileRoot "$folderName.json"
            if (Test-Path $versionJsonPath) {
                $json = Get-Content $versionJsonPath -Raw | ConvertFrom-Json
                $alreadySet = $false
                foreach ($entry in $json.arguments.jvm) {
                    if ($entry.values -and ($entry.values -join " ") -match "user\.language") { $alreadySet = $true }
                }
                if (-not $alreadySet) {
                    $newEntry = [pscustomobject]@{ values = @("-Duser.language=en", "-Duser.country=US"); rules = @() }
                    $json.arguments.jvm += $newEntry
                    $json | ConvertTo-Json -Depth 20 | Set-Content -Path $versionJsonPath -Encoding UTF8
                }
            }
        } elseif ($launcherLabel -eq "CurseForge") {
            $instancePath = Join-Path $profileRoot "minecraftinstance.json"
            if (Test-Path $instancePath) {
                $json = Get-Content $instancePath -Raw | ConvertFrom-Json
                $current = $json.javaArgsOverride
                if (-not $current -or $current -notmatch "user\.language") {
                    $combined = if ($current) { "$current $localeArgs" } else { $localeArgs }
                    $json.javaArgsOverride = $combined
                    $json | ConvertTo-Json -Depth 20 | Set-Content -Path $instancePath -Encoding UTF8
                }
            }
        } elseif ($launcherLabel -eq "Modrinth") {
            Set-AnuModrinthJvmArgs $profileRoot
        }
    } catch { }
}

function Get-AnuSqlitePath {
    # sqlite3.exe ships next to our own exe (Inno Setup installs both).
    try {
        $exeDir = Split-Path ([Diagnostics.Process]::GetCurrentProcess().MainModule.FileName) -Parent
        $candidate = Join-Path $exeDir "sqlite3.exe"
        if (Test-Path $candidate) { return $candidate }
    } catch { }
    return $null
}

function Remove-AnuModrinthFileRecords([string]$profileRoot, $fileNames) {
    # Modrinth records every file it installed in its own database. Deleting a
    # jar from disk without clearing that row makes the launcher refuse to
    # start the instance - "needs repair or re-import" - so the rows have to go
    # with the files. Modrinth is already closed by Close-AnuLauncherApps.
    if (-not $fileNames -or @($fileNames).Count -eq 0) { return }
    $sqlite = Get-AnuSqlitePath
    if (-not $sqlite) { return }
    $db = Join-Path $env:APPDATA "ModrinthApp\app.db"
    if (-not (Test-Path $db)) { return }
    $folder = (Split-Path $profileRoot -Leaf).Replace("'", "''")
    foreach ($name in @($fileNames)) {
        $rel = ("mods/" + $name).Replace("'", "''")
        $match = "SELECT f.id FROM instance_files f JOIN instances i ON i.id = f.instance_id WHERE i.path = '$folder' AND f.relative_path = '$rel'"
        $sql = @"
DELETE FROM instance_content_entries WHERE file_id IN ($match);
DELETE FROM store_instance_files WHERE file_id IN ($match);
DELETE FROM instance_files WHERE id IN ($match);
"@
        try { & $sqlite $db $sql 2>&1 | Out-Null } catch { }
    }
}

function Set-AnuModrinthJvmArgs([string]$profileRoot) {
    # Modrinth keeps launch settings in a SQLite database rather than a file
    # per instance: settings.extra_launch_args is the global "Java arguments"
    # box, instance_launch_overrides.overrides holds the per-instance one.
    # Both are stored as SQLite JSONB blobs, so they have to be written back
    # with jsonb() to stay in that format.
    $sqlite = Get-AnuSqlitePath
    if (-not $sqlite) { return }
    $db = Join-Path $env:APPDATA "ModrinthApp\app.db"
    if (-not (Test-Path $db)) { return }

    $argsJson = '["-Duser.language=en","-Duser.country=US"]'
    $folderName = (Split-Path $profileRoot -Leaf).Replace("'", "''")

    # Append rather than assign, and skip rows that already force a locale, so
    # arguments the player set themselves (heap size etc) survive.
    $sql = @"
UPDATE settings
   SET extra_launch_args = jsonb(json_insert(json(extra_launch_args),
       '`$[#]', '-Duser.language=en', '`$[#]', '-Duser.country=US'))
 WHERE id = 0
   AND json(extra_launch_args) NOT LIKE '%user.language%';
UPDATE instance_launch_overrides
   SET overrides = jsonb_set(overrides, '`$.extra_launch_args', jsonb('$argsJson'))
 WHERE instance_id IN (SELECT id FROM instances WHERE path = '$folderName')
   AND json_extract(overrides, '`$.extra_launch_args') IS NULL;
UPDATE instance_launch_overrides
   SET overrides = jsonb_set(overrides, '`$.extra_launch_args',
       jsonb(json_insert(json_extract(overrides, '`$.extra_launch_args'),
       '`$[#]', '-Duser.language=en', '`$[#]', '-Duser.country=US')))
 WHERE instance_id IN (SELECT id FROM instances WHERE path = '$folderName')
   AND json_extract(overrides, '`$.extra_launch_args') IS NOT NULL
   AND json_extract(overrides, '`$.extra_launch_args') NOT LIKE '%user.language%';
"@
    try { & $sqlite $db $sql 2>&1 | Out-Null } catch { }
}

# Turn the pack's resource packs on in options.txt so nobody has to open the
# Resource Packs screen. index.json lists them lowest-priority first, the same
# order Minecraft stores them. Whatever else the player has enabled stays;
# only the pack's own entries are rewritten so their order stays right.
#
# incompatibleResourcePacks gets ONLY the packs whose pack_format really
# doesn't match the game (Icon Fresh's 34 on 1.20.1): without that entry the
# game drops them, but a compatible pack listed there is dropped too - the
# game "removes it from the incompatibility list" and skips selecting it on
# that launch, then saves options.txt without it.
function ConvertTo-AnuJsonStringArray($items) {
    $parts = @($items | ForEach-Object { '"' + ($_ -replace '\\', '\\' -replace '"', '\"') + '"' })
    return '[' + ($parts -join ',') + ']'
}

function Set-AnuOptionsList([string[]]$lines, [string]$key, $ours, $remove, [bool]$ensureVanilla) {
    $idx = -1
    for ($i = 0; $i -lt $lines.Count; $i++) {
        if ($lines[$i].StartsWith("${key}:")) { $idx = $i; break }
    }
    $existing = @()
    if ($idx -ge 0) {
        try { $existing = @(ConvertFrom-Json $lines[$idx].Substring($key.Length + 1)) } catch { $existing = @() }
    }
    $keep = @($existing | Where-Object { $_ -and $ours -notcontains $_ -and $remove -notcontains $_ })
    if ($ensureVanilla -and $keep -notcontains 'vanilla') { $keep = @('vanilla') + $keep }
    $newLine = "${key}:" + (ConvertTo-AnuJsonStringArray (@($keep) + @($ours)))
    if ($idx -ge 0) { $lines[$idx] = $newLine } else { $lines += $newLine }
    return $lines
}

# pack_format the game expects for a given Minecraft version.
function Get-AnuExpectedPackFormat([string]$mcVersion) {
    switch -Wildcard ($mcVersion) {
        "1.20"   { return 15 }  "1.20.1" { return 15 }
        "1.20.2" { return 18 }
        "1.20.3" { return 22 }  "1.20.4" { return 22 }
        "1.20.5" { return 32 }  "1.20.6" { return 32 }
        "1.21"   { return 34 }  "1.21.1" { return 34 }
        "1.21.2" { return 42 }  "1.21.3" { return 42 }
        "1.21.4" { return 46 }
        "1.21.5" { return 55 }
        "1.21.6" { return 63 }
        "1.21.7" { return 64 }  "1.21.8" { return 64 }
        default  { return $null }
    }
}

function Test-AnuResourcePackCompatible([string]$zipPath, [string]$mcVersion) {
    $expected = Get-AnuExpectedPackFormat $mcVersion
    if (-not $expected) { return $true }
    try {
        Add-Type -AssemblyName System.IO.Compression.FileSystem -ErrorAction Stop
        $zip = [System.IO.Compression.ZipFile]::OpenRead($zipPath)
        try {
            $entry = $zip.GetEntry("pack.mcmeta")
            if (-not $entry) { return $true }
            $reader = New-Object System.IO.StreamReader($entry.Open())
            $meta = (ConvertFrom-Json $reader.ReadToEnd()).pack
            $reader.Close()
        } finally { $zip.Dispose() }
        if ([int]$meta.pack_format -eq $expected) { return $true }
        # supported_formats only counts from 1.20.2 (pack_format 18) on
        if ($expected -ge 18 -and $meta.supported_formats) {
            $sf = $meta.supported_formats
            if ($sf -is [array] -and $sf.Count -eq 2) { return ([int]$sf[0] -le $expected -and $expected -le [int]$sf[1]) }
            if ($sf.min_inclusive) { return ([int]$sf.min_inclusive -le $expected -and $expected -le [int]$sf.max_inclusive) }
        }
        return $false
    } catch { return $true }
}

function Set-AnuEnabledResourcePacks([string]$profileRoot, $packNames, [string]$mcVersion) {
    $names = @($packNames | Where-Object { $_ })
    if ($names.Count -eq 0) { return }
    $ours = @($names | ForEach-Object { "file/$_" })
    $incompatible = @()
    foreach ($n in $names) {
        $zip = Join-Path (Join-Path $profileRoot "resourcepacks") $n
        if ((Test-Path -LiteralPath $zip) -and -not (Test-AnuResourcePackCompatible $zip $mcVersion)) { $incompatible += "file/$n" }
    }
    $optionsPath = Join-Path $profileRoot "options.txt"
    $lines = @()
    if (Test-Path -LiteralPath $optionsPath) {
        $lines = @([System.IO.File]::ReadAllLines($optionsPath, [System.Text.Encoding]::UTF8))
    }
    $lines = Set-AnuOptionsList $lines 'resourcePacks' $ours @() $true
    $lines = Set-AnuOptionsList $lines 'incompatibleResourcePacks' $incompatible $ours $false
    try {
        [System.IO.File]::WriteAllLines($optionsPath, [string[]]$lines, (New-Object System.Text.UTF8Encoding $false))
    } catch {
        Write-AnuDebugLog "options.txt yazilamadi ($optionsPath): $($_.Exception.Message)"
    }
}

Add-ButtonClick $btnUpdate "Yüklenecek mod paketini seçiniz." {
    $ProgressPreference = 'SilentlyContinue'
    Close-AnuLauncherApps

    # selectedTarget is the PROFILE ROOT - the pack syncs mods\, config\,
    # resourcepacks\ and datapacks\ underneath it, not just mods\.
    $profileRoot = $script:selectedTarget
    Close-AnuGameProcess $profileRoot
    if ($script:selectedLauncherData) { Set-AnuLauncherJvmArgs $profileRoot $script:selectedLauncherData.Label }
    if (-not (Test-Path $profileRoot)) {
        New-Item -ItemType Directory -Path $profileRoot -Force | Out-Null
    }

    $modsSubfolder = Join-Path $profileRoot "mods"
    $isFreshInstall = -not (Test-Path $modsSubfolder) -or @(Get-ChildItem -Path $modsSubfolder -Filter *.jar -File -ErrorAction SilentlyContinue).Count -eq 0
    $win = New-AnuProgressWindow $(if ($isFreshInstall) { "İndiriliyor..." } else { "Güncelleniyor..." })
    $win.Bar.Style = "Marquee"

    try {
        $manifest = Invoke-RestMethod -Uri $script:selectedPack.manifest_url -Headers @{ "Cache-Control" = "no-cache" }
    } catch {
        $win.Form.Close()
        Show-AnuDialog "Manifest indirilemedi:`n$($_.Exception.Message)" | Out-Null
        return
    }

    $toDownload = @()
    foreach ($f in $manifest.files) {
        $relPath = Get-ManifestRelPath $f
        $localPath = Join-Path $profileRoot $relPath
        if (-not (Test-Path -LiteralPath $localPath)) {
            $toDownload += @{ file = $f; rel = $relPath }; continue
        }
        if (Test-AnuSeedOnlyPath $f.path) { continue }
        if ((Get-FileSha256 $localPath) -ne $f.sha256) { $toDownload += @{ file = $f; rel = $relPath } }
    }

    # A jar the pack dropped has to go, or the player keeps a mod the server
    # doesn't run: they still pass Forge's mod-list check, then get kicked
    # mid-join with a ResourceLocationException when a packet no longer decodes.
    # Only loose .jar files directly in mods\ are removed - subfolders hold
    # things the game generates for itself (Palladium's documentation dump,
    # Connector's remapped-jar cache), and config\ and resourcepacks\ are the
    # player's own to keep.
    $packModFiles = @{}
    foreach ($f in $manifest.files) {
        $p = ($f.path -replace '\\', '/')
        $parts = $p -split '/'
        if ($parts.Count -eq 2 -and $parts[0] -eq 'mods') { $packModFiles[$parts[1]] = $true }
    }
    $removedMods = @()
    if ($packModFiles.Count -gt 0 -and (Test-Path $modsSubfolder)) {
        Get-ChildItem -LiteralPath $modsSubfolder -Filter *.jar -File -ErrorAction SilentlyContinue | ForEach-Object {
            if (-not $packModFiles.ContainsKey($_.Name)) {
                try {
                    [System.IO.File]::SetAttributes($_.FullName, [System.IO.FileAttributes]::Normal)
                    Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Stop
                    $removedMods += $_.Name
                } catch { }
            }
        }
    }
    if ($removedMods.Count -gt 0) { Remove-AnuModrinthFileRecords $profileRoot $removedMods }

    # Only flag "extra" files inside subfolders the manifest actually manages
    # (mods\, and config\/resourcepacks\/datapacks\ when the pack ships any) -
    # anything the player put in an unmanaged folder (their own shaderpacks,
    # screenshots, saves) is never touched or reported on.
    $manifestRelPaths = @($manifest.files | ForEach-Object { Get-ManifestRelPath $_ })
    $managedSubfolders = $manifestRelPaths | ForEach-Object { ($_ -split '[\\/]')[0] } | Select-Object -Unique
    $extra = @()
    foreach ($sub in $managedSubfolders) {
        $subPath = Join-Path $profileRoot $sub
        if (-not (Test-Path $subPath)) { continue }
        Get-ChildItem -Path $subPath -Recurse -File -ErrorAction SilentlyContinue | ForEach-Object {
            $rel = $_.FullName.Substring($profileRoot.Length).TrimStart('\', '/')
            if ($manifestRelPaths -notcontains $rel) { $extra += $rel }
        }
    }

    $win.Bar.Style = "Blocks"
    $errorCount = 0
    if ($toDownload.Count -gt 0) {
        $win.Bar.Maximum = $toDownload.Count
        $i = 0
        foreach ($item in $toDownload) {
            $i++
            $dest = Join-Path $profileRoot $item.rel
            $destDir = Split-Path $dest -Parent
            if (-not (Test-Path $destDir)) { New-Item -ItemType Directory -Path $destDir -Force | Out-Null }
            try {
                Save-AnuUrlToFile $item.file.url $dest
                $win.Bar.Value = $i
            } catch {
                $errorCount++
                Write-AnuDebugLog "Download failed rel=$($item.rel) url=$($item.file.url): $($_.Exception.Message)"
            }
            [System.Windows.Forms.Application]::DoEvents()
        }
    }

    Set-AnuEnabledResourcePacks $profileRoot $script:selectedPack.enabled_resourcepacks $script:selectedPack.mc_version

    $cfg.targets | Add-Member -NotePropertyName $script:selectedPack.id -NotePropertyValue $profileRoot -Force
    Save-Config $cfg

    $win.Form.Close()

    $summary = if ($toDownload.Count -eq 0) {
        "Her şey güncel, indirilecek dosya yok."
    } else {
        "$($toDownload.Count) dosyadan $($toDownload.Count - $errorCount) tanesi indirildi."
    }
    if ($errorCount -gt 0) { $summary += "`n$errorCount dosya indirilemedi." }
    if ($removedMods.Count -gt 0) { $summary += "`nPaketten çıkarılan $($removedMods.Count) mod silindi." }
    if ($extra.Count -gt 0) { $summary += "`nPakette olmayan $($extra.Count) ekstra dosya var (dokunulmadı)." }
    Show-AnuDialog $summary | Out-Null
}

$script:pendingUpdateUrl = $null

function Check-ForLiveUpdate {
    try {
        $idx = Invoke-RestMethod -Uri (Get-AnuIndexUrl) -Headers @{ "Cache-Control" = "no-cache" }
        if ($idx.app -and $idx.app.version -and $idx.app.setup_url) {
            if ([version]$idx.app.version -gt [version]$AppVersion) {
                $script:pendingUpdateUrl = $idx.app.setup_url
                $lblLiveUpdateText.Text = "⟳ v$($idx.app.version)"
                $btnLiveUpdate.Visible = $true
            }
        }
    } catch { }
}

# Uygulama açıkken de güncelleme çıkarsa, aç-kapa gerektirmeden
# versiyon rozetinin yanında küçük bir "Güncelle" düğmesi belirir.
$updateCheckTimer = New-Object System.Windows.Forms.Timer
$updateCheckTimer.Interval = 5 * 60 * 1000
$updateCheckTimer.Add_Tick({ Check-ForLiveUpdate })
$updateCheckTimer.Start()

$liveUpdateClickHandler = {
    if ($script:pendingUpdateUrl) {
        $updateCheckTimer.Stop()
        $btnLiveUpdate.Visible = $false
        Invoke-AnuSelfUpdate $script:pendingUpdateUrl
    }
}
$btnLiveUpdate.Add_Click($liveUpdateClickHandler)
$lblLiveUpdateText.Add_Click($liveUpdateClickHandler)

[void]$form.ShowDialog()
